   "这次选举，本来他是最有希望的，但由于他近来的所作所为不孚众望，结果落选了。※注：人民网关于不负众望和不孚众望的辨析：不负众望”误为“不孚众望”。2022 年12 月18 日，卡塔尔世界杯决赛，阿根廷队击败法国队夺得冠军，梅西不负众望，率领阿根廷队捧起大力神杯。有媒体在报道相关新闻时，把“不负众望”误为了“不孚众望”。“负”指辜负；“不负众望”即没有辜负众人的希望、期待。“孚”读fú，指令人信服，如“深孚众望”便指使大众非常信服，享有很高的威望。“不孚”指不能使人信服，“不孚众望”只能理解成不能使大众信服、辜负了大家的期望。这显然和赞扬梅西的本意大相径庭。"
